/**
 * WorkflowStatusResponse
 *
 * Comprehensive workflow status response.
 *
 * Returned by GET /workflow/{workflow_id}/status endpoint.
 * Provides complete status tracking for image processing and inference workflows.
 *
 * The response includes:
 * - Overall workflow status and type
 * - Parent workflow orchestration status
 * - Image processing pipeline details and timestamps
 * - ML inference workflow status
 * - Authorization metadata
 */
export type WorkflowStatusResponse = {
  /**
   * Workflowid
   *
   * The queried workflow ID
   */
  workflowId: string;
  /**
   * Workflowtype
   *
   * Workflow type: 'parent', 'processing', or 'inference'
   */
  workflowType: string;
  /**
   * Imageid
   *
   * Associated picture UUID
   */
  imageId: string;
  /**
   * Overallstatus
   *
   * High-level status: 'pending', 'in_progress', 'completed', 'failed'
   */
  overallStatus: string;
  /**
   * Authorization metadata
   */
  authorization: WorkflowAuthorization;
  /**
   * Parent workflow status (if exists)
   */
  parentWorkflow?: ParentWorkflowStatus | null;
  /**
   * Processing workflow details (if exists)
   */
  processingWorkflow?: ProcessingWorkflowStatus | null;
  /**
   * Inference workflow details (if exists)
   */
  inferenceWorkflow?: InferenceWorkflowStatus | null;
  /**
   * Errormessage
   *
   * Error message (if failed)
   */
  errorMessage?: string | null;
  /**
   * Errordetails
   *
   * Detailed error info (if failed)
   */
  errorDetails?: string | null;
};

